//! Part 2: `string_enum!`, an enum with its text form.

use std::fmt;

/// Error returned by `FromStr` for types generated by [`string_enum!`].
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct UnknownVariant {
    /// Name of the generated enum, e.g. `"JobState"`.
    pub type_name: &'static str,
    /// The rejected input, verbatim.
    pub input: String,
}

impl fmt::Display for UnknownVariant {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "unknown {} `{}`", self.type_name, self.input)
    }
}

impl std::error::Error for UnknownVariant {}

/// Generates a fieldless enum with a text form for each variant.
///
/// Generated items: the enum (with the caller's attributes plus
/// `Debug, Clone, Copy, PartialEq, Eq, Hash`), `ALL`, `as_str`, `Display`, and
/// `FromStr` (exact, case-sensitive, `Err = UnknownVariant`).
#[macro_export]
macro_rules! string_enum {
    (
        $(#[$meta:meta])*
        $vis:vis enum $name:ident {
            $( $(#[$variant_meta:meta])* $variant:ident = $text:literal ),+ $(,)?
        }
    ) => {
        $(#[$meta])*
        #[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
        $vis enum $name {
            $( $(#[$variant_meta])* $variant, )+
        }

        impl $name {
            /// Every variant, in declaration order.
            $vis const ALL: &'static [Self] = &[$(Self::$variant),+];

            /// The text form of this variant.
            $vis const fn as_str(&self) -> &'static str {
                match self {
                    $( Self::$variant => $text, )+
                }
            }
        }

        impl ::core::fmt::Display for $name {
            fn fmt(&self, f: &mut ::core::fmt::Formatter<'_>) -> ::core::fmt::Result {
                f.write_str(self.as_str())
            }
        }

        impl ::core::str::FromStr for $name {
            type Err = $crate::UnknownVariant;

            fn from_str(s: &str) -> ::core::result::Result<Self, Self::Err> {
                match s {
                    $( $text => ::core::result::Result::Ok(Self::$variant), )+
                    _ => ::core::result::Result::Err($crate::UnknownVariant {
                        type_name: ::core::stringify!($name),
                        input: ::std::string::String::from(s),
                    }),
                }
            }
        }
    };
}
